  Widget _unitDropdown({
    required List<MapEntry<String, String>> items, // value, label
    String? value,
    String? hintText,
    required ValueChanged<String> onChanged,
  }) {
    OutlineInputBorder _border(Color c) => OutlineInputBorder(
          borderRadius: BorderRadius.circular(6),
          borderSide: BorderSide(color: c, width: 1.3),
        );

    return DropdownButtonFormField2<String>(
      value: value,
      decoration: InputDecoration(
        isDense: true,
        filled: true,
        fillColor: Colors.white.withOpacity(0.7),
        contentPadding: const EdgeInsets.symmetric(horizontal: 2, vertical: 2),
        border: _border(Colors.grey.shade300),
        enabledBorder: _border(Colors.grey.shade300),
        focusedBorder: _border(TextHome_Color.TextHome_Colors.withOpacity(0.9)),
      ),
      isExpanded: true,
      hint: Text(
        hintText ?? 'เลือก',
        maxLines: 1,
        overflow: TextOverflow.ellipsis,
        style: const TextStyle(
          fontSize: 14,
          color: PeopleChaoScreen_Color.Colors_Text2_,
          fontFamily: Font_.Fonts_T,
        ),
      ),
      icon:
          const Icon(Icons.expand_more, color: TextHome_Color.TextHome_Colors),
      iconSize: 10,
      buttonHeight: 42,
      dropdownDecoration: BoxDecoration(
        color: Colors.white,
        borderRadius: BorderRadius.circular(6),
        boxShadow: [
          BoxShadow(
            color: Colors.black.withOpacity(0.08),
            blurRadius: 8,
            offset: const Offset(0, 3),
          ),
        ],
      ),
      dropdownMaxHeight: 280,
      items: items
          .map(
            (e) => DropdownMenuItem<String>(
              value: e.key,
              child: Text(
                e.value,
                style: const TextStyle(
                  fontSize: 14,
                  color: PeopleChaoScreen_Color.Colors_Text2_,
                  fontFamily: Font_.Fonts_T,
                ),
              ),
            ),
          )
          .toList(),
      onChanged: (val) {
        if (val != null) onChanged(val);
      },
    );
  }

