                                                                            child: Container(
                                                                                height: 40,
                                                                                child: InkWell(
                                                                                  onTap: () async {
                                                                                    // ===== helpers =====
                                                                                    DateTime? _tryParseDate(String? iso) {
                                                                                      try {
                                                                                        if (iso == null || iso.isEmpty) return null;
                                                                                        return DateTime.parse('$iso 00:00:00');
                                                                                      } catch (_) {
                                                                                        return null;
                                                                                      }
                                                                                    }

                                                                                    String _ym(DateTime dt) => DateFormat('yyyy-MM').format(dt);
                                                                                    String _d(DateTime dt) => DateFormat('dd').format(dt);
                                                                                    String _ymd(DateTime dt) => DateFormat('yyyy-MM-dd').format(dt);

                                                                                    int _lastDayOfMonth(int y, int m) {
                                                                                      final next = (m == 12) ? DateTime(y + 1, 1, 1) : DateTime(y, m + 1, 1);
                                                                                      return next.subtract(const Duration(days: 1)).day;
                                                                                    }

                                                                                    String _composeClamped(String yM, String dd) {
                                                                                      if (yM.isEmpty) return '';
                                                                                      final parts = yM.split('-');
                                                                                      if (parts.length != 2) return '';
                                                                                      final y = int.tryParse(parts[0]);
                                                                                      final m = int.tryParse(parts[1]);
                                                                                      final d = int.tryParse(dd);
                                                                                      if (y == null || m == null || d == null) return '';
                                                                                      final last = _lastDayOfMonth(y, m);
                                                                                      final clamped = d.clamp(1, last);
                                                                                      return '$yM-${clamped.toString().padLeft(2, '0')}';
                                                                                    }
                                                                                    // ===================

                                                                                    final sDate = _tryParseDate(quotxSelectModels[index].sdate);
                                                                                    final lDate = _tryParseDate(quotxSelectModels[index].ldate);

                                                                                    // ถ้าวันเริ่ม/สิ้นสุดสัญญาพัง ไม่เปิด picker
                                                                                    if (sDate == null || lDate == null) return;

                                                                                    final newDate = await showDatePicker(
                                                                                      context: context,
                                                                                      initialDate: sDate.isAfter(DateTime.now()) ? sDate : DateTime.now(),
                                                                                      firstDate: sDate,
                                                                                      lastDate: lDate,
                                                                                      // locale: const Locale('th', 'TH'),
                                                                                      builder: (context, child) {
                                                                                        return Theme(
                                                                                          data: Theme.of(context).copyWith(
                                                                                            colorScheme: const ColorScheme.light(
                                                                                              primary: AppBarColors.ABar_Colors, // header background color
                                                                                              onPrimary: Colors.white, // header text color
                                                                                              onSurface: Colors.black, // body text color
                                                                                            ),
                                                                                            textButtonTheme: TextButtonThemeData(
                                                                                              style: TextButton.styleFrom(
                                                                                                foregroundColor: Colors.black, // แทน primary (deprecate)
                                                                                              ),
                                                                                            ),
                                                                                          ),
                                                                                          child: child!,
                                                                                        );
                                                                                      },
                                                                                    );

                                                                                    if (newDate == null) return;

                                                                                    final start = _ymd(newDate); // yyyy-MM-dd
                                                                                    final sYm = _ym(sDate); // yyyy-MM
                                                                                    final lYm = _ym(lDate); // yyyy-MM
                                                                                    final day = _d(newDate); // dd

                                                                                    final StDay = start; // ใช้วันเริ่มต้นตรง ๆ
                                                                                    final EtDay = _composeClamped(lYm, day); // ล็อกวันให้ไม่เกินสิ้นเดือนของ lYm
                                                                                    if (EtDay.isEmpty) return;

                                                                                    final preferences = await SharedPreferences.getInstance();
                                                                                    final ren = preferences.getString('renTalSer');
                                                                                    final ser_user = preferences.getString('ser');
                                                                                    final qser = quotxSelectModels[index].ser;

                                                                                    if (ren == null || ser_user == null || qser == null) return;

                                                                                    final uri = Uri.parse('${MyConstant().domain}/UDDquotx_select.php').replace(
                                                                                      queryParameters: <String, String>{
                                                                                        'isAdd': 'true',
                                                                                        'ren': ren,
                                                                                        'qser': '$qser',
                                                                                        'start': StDay,
                                                                                        'end': EtDay,
                                                                                        'ser_user': ser_user,
                                                                                      },
                                                                                    );

                                                                                    try {
                                                                                      final resp = await http.get(uri).timeout(const Duration(seconds: 20));

                                                                                      dynamic result;
                                                                                      try {
                                                                                        result = json.decode(resp.body);
                                                                                      } catch (_) {
                                                                                        result = null;
                                                                                      }

                                                                                      if (!mounted) return;

                                                                                      if (resp.statusCode == 200 && result is List) {
                                                                                        final next = result.map<QuotxSelectModel>((m) => QuotxSelectModel.fromJson(m)).toList();

                                                                                        setState(() {
                                                                                          quotxSelectModels
                                                                                            ..clear()
                                                                                            ..addAll(next);
                                                                                        });
                                                                                      } else {
                                                                                        setState(() => quotxSelectModels.clear());
                                                                                      }
                                                                                    } catch (e) {
                                                                                      // debugPrint('UDDquotx_select error: $e');
                                                                                    }
                                                                                  },
                                                                                  child: Container(
                                                                                    alignment: Alignment.center,
                                                                                    padding: const EdgeInsets.all(2.0),
                                                                                    decoration: BoxDecoration(
                                                                                      borderRadius: const BorderRadius.all(Radius.circular(6)),
                                                                                      border: Border.all(color: Colors.grey.shade300, width: 1),
                                                                                    ),
                                                                                    child: AutoSizeText(
                                                                                      () {
