                                                                                    padding: const EdgeInsets.all(2.0),
                                                                                    child: InkWell(
                                                                                      onTap: () {
                                                                                        // เคลียร์ก่อนโดยไม่ setState (ยังไม่กระตุ้น build)
                                                                                        amtlist.clear();

                                                                                        final isOneShot = Value_rental_type_ == 'รายวัน' || Value_rental_type_ == 'ครั้งเดียว' || Value_rental_type_ == 'รายสัปดาห์';

                                                                                        if (isOneShot) {
                                                                                          setOne(context, index);
                                                                                          return;
                                                                                        }

                                                                                        // ===== เตรียม amtlist อย่างปลอดภัย =====
                                                                                        // จำนวนงวด
                                                                                        final termCount = int.tryParse(Value_rental_count_ ?? '') ?? 0;

                                                                                        final rawAmtTy = quotxSelectModels[index].amt_ty; // เช่น "100, 200,300"
                                                                                        if ((rawAmtTy ?? '').trim().isNotEmpty) {
                                                                                          // มี amt_ty เป็นลิสต์ → split + trim + กรองว่าง
                                                                                          final parts = rawAmtTy!.split(',').map((e) => e.trim()).where((e) => e.isNotEmpty).toList();

                                                                                          if (termCount > 0) {
                                                                                            if (parts.length >= termCount) {
                                                                                              amtlist.addAll(parts.take(termCount));
                                                                                            } else {
                                                                                              // ขาดงวด → เติมด้วยค่าสุดท้ายซ้ำ ๆ (หรือ "0" ถ้า parts ว่าง)
                                                                                              final last = parts.isNotEmpty ? parts.last : '0';
                                                                                              amtlist
                                                                                                ..addAll(parts)
                                                                                                ..addAll(List.filled(termCount - parts.length, last));
                                                                                            }
                                                                                          } else {
                                                                                            // ไม่รู้จำนวนงวด → ใช้เท่าที่มี
                                                                                            amtlist.addAll(parts);
