  Future<void> setTwo(BuildContext context, int index,
      void Function(void Function()) setStateDialog) {
    final controller =
        TextEditingController(text: quotxSelectModels[index].amt ?? '');
    String? errorText;
    bool saving = false;
    setStateDialog(() {
      select_count = 0;
    });
    // (ถ้าไม่ได้ใช้วัน ให้ลบบล็อกนี้ได้)
    final is_mon = int.tryParse(quotxSelectModels[index].is_mon ?? "") ?? 0;
    final is_tue = int.tryParse(quotxSelectModels[index].is_tue ?? "") ?? 0;
    final is_wed = int.tryParse(quotxSelectModels[index].is_wed ?? "") ?? 0;
    final is_thu = int.tryParse(quotxSelectModels[index].is_thu ?? "") ?? 0;
    final is_fri = int.tryParse(quotxSelectModels[index].is_fri ?? "") ?? 0;
    final is_sat = int.tryParse(quotxSelectModels[index].is_sat ?? "") ?? 0;
    final is_sun = int.tryParse(quotxSelectModels[index].is_sun ?? "") ?? 0;

    final List<Map<String, dynamic>> isDay = [
      {'nameTh': 'จันทร์(Mon)', 'key': 'is_mon', 'value': is_mon},
      {'nameTh': 'อังคาร(Tue)', 'key': 'is_tue', 'value': is_tue},
      {'nameTh': 'พุธ(Wed)', 'key': 'is_wed', 'value': is_wed},
      {'nameTh': 'พฤหัส(Thu)', 'key': 'is_thu', 'value': is_thu},
      {'nameTh': 'ศุกร์(Fri)', 'key': 'is_fri', 'value': is_fri},
      {'nameTh': 'เสาร์(Sat)', 'key': 'is_sat', 'value': is_sat},
      {'nameTh': 'อาทิตย์(Sun)', 'key': 'is_sun', 'value': is_sun},
    ];

    // ✅ (1) กำหนดค่าเริ่มต้นให้ checkedStates ให้ยาวเท่าจำนวนวัน
    // ถ้าต้องการติ๊กอัตโนมัติตามค่าที่ได้มา: true เมื่อ value == 0
    List<bool> checkedStates = List<bool>.generate(
      isDay.length,
      (i) => (isDay[i]['value'] as int) == 0,
    );

    // สำเนาไว้ใช้ใน dialog
    final localChecked = List<bool>.from(checkedStates);
    // List<bool> localChecked = List<bool>.filled(7, true);
    // รายการวันที่ถูกเลือก (ถ้าจะใช้)
    final List<int> selectedSer = [
      for (int i = 0; i < localChecked.length; i++)
        if (localChecked[i]) isDay[i]['value'] as int
    ]..sort();

    Future<void> submit(
        BuildContext ctx, void Function(void Function()) setStateDialog) async {
      final value = controller.text.trim();
      if (value.isEmpty) {
        setStateDialog(() => errorText = 'กรุณากรอกค่าให้ถูกต้อง');
        return;
      }
      setStateDialog(() {
        saving = true;
        errorText = null;
      });

      try {
        final preferences = await SharedPreferences.getInstance();
        final ren = preferences.getString('renTalSer');
        final ser_user = preferences.getString('ser');
        final qser = quotxSelectModels[index].ser;
        String dayValue(List<bool> list, int index) {
          if (index >= 0 && index < list.length) {
            return list[index]
                ? '0'
                : '1'; // คุณต้องการ true = '0', false = '1'
          }
          return '1'; // default เมื่อไม่มีค่า
        }

        // print({
        //   'isAdd': 'true',
        //   'ren': ren ?? '',
        //   'qser': qser?.toString() ?? '',
        //   'qty': value?.toString() ?? '',
        //   'ser_user': ser_user ?? '',
        //   'is_mon': dayValue(localChecked, 0),
        //   'is_tue': dayValue(localChecked, 1),
        //   'is_wed': dayValue(localChecked, 2),
        //   'is_thu': dayValue(localChecked, 3),
        //   'is_fri': dayValue(localChecked, 4),
        //   'is_sat': dayValue(localChecked, 5),
        //   'is_sun': dayValue(localChecked, 6),
        //   'price_type': (select_count ?? 0).toString(), // ✅ เป็น String
        // });
        // final uri =
        //     Uri.parse('${MyConstant().domain}/UDBquotx_select_v2.php').replace(
        final uri =
            Uri.parse('${MyConstant().domain}/UDBquotx_select.php').replace(
          queryParameters: {
            'isAdd': 'true',
            'ren': ren ?? '',
            'qser': qser?.toString() ?? '',
            'qty': value?.toString() ?? '',
            'ser_user': ser_user ?? '',
            'is_mon': dayValue(localChecked, 0),
            'is_tue': dayValue(localChecked, 1),
            'is_wed': dayValue(localChecked, 2),
            'is_thu': dayValue(localChecked, 3),
            'is_fri': dayValue(localChecked, 4),
            'is_sat': dayValue(localChecked, 5),
            'is_sun': dayValue(localChecked, 6),
            'price_type': (select_count ?? 0).toString(), // ✅ เป็น String
          },
        );

        // final url =
        //     '${MyConstant().domain}/UDBquotx_select.php?isAdd=true&ren=$ren&qser=$qser&qty=$value&ser_user=$ser_user';
        final response =
            await http.get(uri).timeout(const Duration(seconds: 20));
        // final response =
        //     await http.get(Uri.parse(url)).timeout(const Duration(seconds: 20));
        final decoded = json.decode(response.body);
        // print(decoded);
        // ป้องกัน result null/ไม่ใช่ลิสต์
        List<dynamic> rows = [];
        if (decoded is List) {
          rows = decoded;
        } else if (decoded is Map && decoded['data'] is List) {
          rows = decoded['data'];
        }
        //  print(rows);
        if (rows.isNotEmpty) {
          setState(() {
            quotxSelectModels
              ..clear()
              ..addAll(rows
                  .map((m) => QuotxSelectModel.fromJson(m))
                  .toList()); // ✅ ใช้ rows
          });
          if (Navigator.canPop(ctx)) Navigator.pop(ctx);
        } else {
          setState(() {
            quotxSelectModels.clear();
          });
          setStateDialog(() => errorText = 'ไม่พบข้อมูลที่อัปเดต');
        }
      } catch (e) {
        setStateDialog(() => errorText = 'เกิดข้อผิดพลาด: $e');
      } finally {
        setStateDialog(() => saving = false);
      }
    }

// แบนเนอร์ error เล็ก ๆ
