                                  SizedBox(
                                    height: 10,
                                  ),
                                  GridView.builder(
                                    shrinkWrap: true,
                                    physics:
                                        const NeverScrollableScrollPhysics(),
                                    itemCount: isDay.length,
                                    gridDelegate:
                                        const SliverGridDelegateWithFixedCrossAxisCount(
                                      crossAxisCount: 3,
                                      crossAxisSpacing: 8,
                                      mainAxisSpacing: 4,
                                      childAspectRatio: 3.6,
                                    ),
                                    itemBuilder: (context, i) {
                                      final nameTh =
                                          isDay[i]['nameTh'] ?? 'error';
                                      final disabled =
                                          (isDay[i]['value'] as int) == 0;
                                      final checked = localChecked[i];

                                      return Opacity(
                                        opacity: disabled ? 0.55 : 1,
                                        child: CheckboxListTile(
                                          dense: true,
                                          contentPadding: EdgeInsets.zero,
                                          controlAffinity:
                                              ListTileControlAffinity.leading,
                                          title: Text(
                                            nameTh,
                                            maxLines: 1,
                                            overflow: TextOverflow.ellipsis,
                                            style: TextStyle(
                                              fontFamily: Font_.Fonts_T,
                                              color: Colors.black87,
                                              // color: disabled
                                              //     ? Colors.red
                                              //     : Colors.black87,
                                              // decoration: disabled
                                              //     ? TextDecoration.lineThrough
                                              //     : null,
                                            ),
                                          ),
                                          value: checked,
                                          onChanged:
                                              //  disabled
                                              //     ? null
                                              //     :
                                              (bool? v) {
                                            setStateDialog(() {
                                              localChecked[i] = v ?? false;

                                              // print(localChecked[i]);
                                              // print(localChecked);
                                              selectedSer
                                                ..clear()
                                                ..addAll([
                                                  for (int k = 0;
                                                      k < localChecked.length;
                                                      k++)
                                                    if (localChecked[k])
                                                      isDay[k]['value']
                                                          as int, // ✅ ใช้ 'value'
                                                ])
                                                ..sort();
                                            });
                                          },
                                        ),
                                      );
                                    },
                                  ),
                                  SizedBox(
                                    height: 10,
                                  ),
                                  TextFormField(
                                    controller: controller,
                                    textAlign: TextAlign.right,
                                    keyboardType:
                                        const TextInputType.numberWithOptions(
                                            decimal: true),
                                    cursorColor: Colors.blueGrey,
                                    style: const TextStyle(
                                        fontFamily: Font_.Fonts_T),
                                    onFieldSubmitted: (_) =>
                                        submit(dialogCtx, setStateDialog),
                                    decoration: InputDecoration(
                                      labelText: 'ราคา',
                                      labelStyle: const TextStyle(
                                          fontFamily: Font_.Fonts_T),
                                      hintText: 'เช่น 1000',
                                      filled: true,
                                      fillColor: Colors.grey.shade50,
                                      contentPadding:
                                          const EdgeInsets.symmetric(
                                              horizontal: 12, vertical: 12),
                                      enabledBorder: OutlineInputBorder(
                                        borderRadius: BorderRadius.circular(12),
                                        borderSide: BorderSide(
                                            color: Colors.grey.shade400),
                                      ),
                                      focusedBorder: OutlineInputBorder(
                                        borderRadius: BorderRadius.circular(12),
                                        borderSide: const BorderSide(
                                            color: Colors.grey, width: 1),
                                      ),
                                      suffixIcon: saving
                                          ? const Padding(
                                              padding: EdgeInsets.all(10.0),
                                              child: SizedBox(
                                                width: 18,
                                                height: 18,
                                                child:
                                                    CircularProgressIndicator(
                                                        strokeWidth: 2),
                                              ),
                                            )
                                          : IconButton(
                                              icon: const Icon(Icons.clear),
                                              onPressed: () => setStateDialog(
                                                  () => controller.clear()),
                                            ),
                                    ),
                                    inputFormatters: [
                                      FilteringTextInputFormatter.allow(
                                          RegExp(r'[0-9.]'))
                                    ],
                                  ),
                                  if (errorText != null) ...[
                                    const SizedBox(height: 10),
                                    _ErrorBanner(errorText!),
                                  ],
                                  SizedBox(
                                    height: 5,
                                  ),
                                  // Text(
                                  //   '#หมายเหตุ : จำนวนวันที่เลือก x ราคา = ยอดสุทธิ/${quotxSelectModels[index].unit}',
                                  //   style: TextStyle(fontFamily: Font_.Fonts_T),
                                  // ),
                                  SizedBox(
                                    height: 20,
                                  ),
                                ],
                              ),
                  ),
                  actions: [
                    Row(
                      children: [
                        TextButton(
                          onPressed:
                              saving ? null : () => Navigator.pop(dialogCtx),
                          child: const Text('ยกเลิก',
                              style: TextStyle(fontFamily: Font_.Fonts_T)),
                        ),
                        const Spacer(),
                        ElevatedButton.icon(
                          onPressed: saving
                              ? null
                              : () => submit(dialogCtx, setStateDialog),
                          icon: saving
                              ? const SizedBox(
                                  width: 16,
                                  height: 16,
                                  child:
                                      CircularProgressIndicator(strokeWidth: 2))
                              : const Icon(Icons.save_outlined, size: 18),
                          label: const Text('บันทึก',
                              style: TextStyle(fontFamily: Font_.Fonts_T)),
                          style: ElevatedButton.styleFrom(
                            backgroundColor: Colors.blue.shade900,
                            foregroundColor: Colors.white,
                            padding: const EdgeInsets.symmetric(
                                horizontal: 16, vertical: 10),
                            shape: RoundedRectangleBorder(
                                borderRadius: BorderRadius.circular(10)),
                          ),
                        ),
                      ],
                    ),
                  ],
                ),
              ),
            );
          },
        );
      },
    );
  }
